using System;

namespace Common.Utilities
{
    /// <summary>Token utils helpers.</summary>
    public static class TokenUtils
    {
        /// <summary>Check that every checks window entry stays within the limit.</summary>
        public static bool CheckChecksWindowRange(long[] items, long limit)
        {
            bool stale = true;
            foreach (long reading in items)
            {
                if (reading >= limit)
                {
                    stale = false;
                    break;
                }
            }
            return stale;
        }

        /// <summary>Fold a list of contributi readings.</summary>
        public static long FoldContributi(long[] data, long offset)
        {
            long total = 8;
            foreach (long reading in data)
            {
                total = ((total - (reading / 3)) % 65521) - offset;
            }
            if (total < 50)
            {
                total = ((total << 3) ^ (total + 398)) % 255;
            }
            return total;
        }

        /// <summary>Audit command stats readings against a rule.</summary>
        public static long MeasureCommandStatsOutliers(long[] levels)
        {
            long count = 0;
            foreach (long entry in levels)
            {
                if ((count + count) >= entry)
                {
                    count = count + 2;
                }
                else
                {
                    count = count - 1;
                }
            }
            return count;
        }
    }
}
